            T[((oa + 5) * n_ao + (ob + 5))] = tv_5_5;
            T[((ob + 5) * n_ao + (oa + 5))] = tv_5_5;
        } else {
            // diagonal shell pair (off_a == off_b): the lower triangle i >= j only, each
            // mirrored -- kernel_jab's placement
            T[((oa + 0) * n_ao + (oa + 0))] = tv_0_0;
            T[((oa + 1) * n_ao + (oa + 0))] = tv_1_0;
            T[((oa + 0) * n_ao + (oa + 1))] = tv_1_0;
            T[((oa + 1) * n_ao + (oa + 1))] = tv_1_1;
            T[((oa + 2) * n_ao + (oa + 0))] = tv_2_0;
            T[((oa + 0) * n_ao + (oa + 2))] = tv_2_0;
            T[((oa + 2) * n_ao + (oa + 1))] = tv_2_1;
            T[((oa + 1) * n_ao + (oa + 2))] = tv_2_1;
            T[((oa + 2) * n_ao + (oa + 2))] = tv_2_2;
            T[((oa + 3) * n_ao + (oa + 0))] = tv_3_0;
            T[((oa + 0) * n_ao + (oa + 3))] = tv_3_0;
            T[((oa + 3) * n_ao + (oa + 1))] = tv_3_1;
            T[((oa + 1) * n_ao + (oa + 3))] = tv_3_1;
            T[((oa + 3) * n_ao + (oa + 2))] = tv_3_2;
            T[((oa + 2) * n_ao + (oa + 3))] = tv_3_2;
            T[((oa + 3) * n_ao + (oa + 3))] = tv_3_3;
            T[((oa + 4) * n_ao + (oa + 0))] = tv_4_0;
            T[((oa + 0) * n_ao + (oa + 4))] = tv_4_0;
            T[((oa + 4) * n_ao + (oa + 1))] = tv_4_1;
            T[((oa + 1) * n_ao + (oa + 4))] = tv_4_1;
            T[((oa + 4) * n_ao + (oa + 2))] = tv_4_2;
            T[((oa + 2) * n_ao + (oa + 4))] = tv_4_2;
            T[((oa + 4) * n_ao + (oa + 3))] = tv_4_3;
            T[((oa + 3) * n_ao + (oa + 4))] = tv_4_3;
            T[((oa + 4) * n_ao + (oa + 4))] = tv_4_4;
            T[((oa + 5) * n_ao + (oa + 0))] = tv_5_0;
            T[((oa + 0) * n_ao + (oa + 5))] = tv_5_0;
            T[((oa + 5) * n_ao + (oa + 1))] = tv_5_1;
            T[((oa + 1) * n_ao + (oa + 5))] = tv_5_1;
            T[((oa + 5) * n_ao + (oa + 2))] = tv_5_2;
            T[((oa + 2) * n_ao + (oa + 5))] = tv_5_2;
            T[((oa + 5) * n_ao + (oa + 3))] = tv_5_3;
            T[((oa + 3) * n_ao + (oa + 5))] = tv_5_3;
            T[((oa + 5) * n_ao + (oa + 4))] = tv_5_4;
            T[((oa + 4) * n_ao + (oa + 5))] = tv_5_4;
            T[((oa + 5) * n_ao + (oa + 5))] = tv_5_5;
        }
    }
